const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT || 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20
});

const ALGORITHM = 'aes-256-cbc';
const KEY = Buffer.from(process.env.ENC_KEY || 'a'.repeat(64), 'hex');

function decrypt(encryptedHex) {
  const data = Buffer.from(encryptedHex, 'hex');
  const iv = data.slice(0, 16);
  const ciphertext = data.slice(16);
  const decipher = crypto.createDecipheriv(ALGORITHM, KEY, iv);
  let decrypted = decipher.update(ciphertext);
  decrypted = Buffer.concat([decrypted, decipher.final()]);
  return decrypted.toString('utf8');
}

function encrypt(plaintext) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv(ALGORITHM, KEY, iv);
  let encrypted = cipher.update(plaintext, 'utf8');
  encrypted = Buffer.concat([encrypted, cipher.final()]);
  return Buffer.concat([iv, encrypted]).toString('hex');
}

// Token-based session lookup
app.post('/api/session/validate', async (req, res) => {
  const { token } = req.body;
  if (!token || typeof token !== 'string') {
    return res.status(400).json({ error: 'Missing token' });
  }

  try {
    const sessionData = decrypt(token);
    const parsed = JSON.parse(sessionData);

    // Parameterized query - safe from SQLi
    const result = await pool.query(
      'SELECT user_id, role, email FROM users WHERE user_id = $1 AND active = true',
      [parsed.userId]
    );

    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'Invalid session' });
    }

    return res.status(200).json({
      valid: true,
      user: result.rows[0],
      expires: parsed.exp
    });
  } catch (err) {
    // Padding oracle: different error messages for different failure modes
    if (err.message.includes('bad decrypt') || err.message.includes('wrong final block')) {
      return res.status(400).json({ error: 'Decryption failed: invalid padding' });
    }
    if (err instanceof SyntaxError) {
      return res.status(400).json({ error: 'Malformed session payload' });
    }
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Issue encrypted session token
app.post('/api/session/create', async (req, res) => {
  const { username, password } = req.body;

  const result = await pool.query(
    'SELECT user_id, password_hash FROM users WHERE email = $1',
    [username]
  );

  if (result.rows.length === 0) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const user = result.rows[0];
  const hash = crypto.createHash('sha256').update(password).digest('hex');

  if (hash !== user.password_hash) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const sessionPayload = JSON.stringify({
    userId: user.user_id,
    exp: Date.now() + 3600000,
    nonce: crypto.randomBytes(8).toString('hex')
  });

  const token = encrypt(sessionPayload);
  return res.status(200).json({ token });
});

// Admin endpoint
app.get('/api/admin/users', async (req, res) => {
  const authToken = req.headers['x-session-token'];
  if (!authToken) return res.status(401).json({ error: 'No token' });

  try {
    const sessionData = decrypt(authToken);
    const parsed = JSON.parse(sessionData);

    const result = await pool.query(
      'SELECT user_id, role FROM users WHERE user_id = $1',
      [parsed.userId]
    );

    if (result.rows.length === 0 || result.rows[0].role !== 'admin') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const users = await pool.query('SELECT user_id, email, role FROM users');
    return res.status(200).json({ users: users.rows });
  } catch (err) {
    if (err.message.includes('bad decrypt') || err.message.includes('wrong final block')) {
      return res.status(400).json({ error: 'Decryption failed: invalid padding' });
    }
    return res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(3000, () => console.log('Server running on port 3000'));
